parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "categoria": {
      "type": "string",
      "enum": [
        "VENTAS",
        "CONSULTA",
        "SOPORTE",
        "HUMANO",
        "OTRO"
      ],
      "description": "Clasificación del correo"
    },
    "prioridad": {
      "type": "string",
      "enum": [
        "alta",
        "normal"
      ],
      "description": "alta si es HUMANO, reclamo o urgencia"
    },
    "resumen": {
      "type": "string",
      "description": "Lo que pide el remitente, en una oración de hasta 25 palabras"
    },
    "respuesta": {
      "type": "string",
      "description": "Cuerpo del correo de respuesta, sin asunto"
    }
  },
  "required": [
    "categoria",
    "prioridad",
    "resumen",
    "respuesta"
  ],
  "additionalProperties": false
}

{
  "type": "object",
  "properties": {
    "asunto_principal": { "type": "string", "description": "Tema central de la conversación en una oración" },
    "puntos_clave": { "type": "array", "items": { "type": "string" }, "minItems": 1, "maxItems": 6, "description": "Datos concretos que dio el usuario" },
    "accion_requerida": { "type": "string", "description": "Próxima acción concreta para el equipo de IANTOIA" }
  },
  "required": ["asunto_principal", "puntos_clave", "accion_requerida"],
  "additionalProperties": false
}
